-- Mensaje 135 (5-nov-2026) · Mundo 4, tanda 2: las prácticas.
-- 11 guiones (4.1, 4.2, 4.3, 4.6, 4.9, 4.11, 4.12, 4.14, 4.15, 4.16 y 7.3). Cada uno se reemplaza solo si está en la versión esperada;
-- el chequeo del final compara la huella exacta de cada guion y aborta si alguno no quedó. Correrlo dos veces no cambia nada.

UPDATE public.nodes SET practice_script = $g${"notes":"El drill aísla la presentación: el Actor declara su dolor en la primera línea (dado por descubierto). Espejo: conexión → interés y señales; genérico → tibieza sin preguntas. El failure baja_su_valor viene directo de la doctrina de Costo vs Valor.","scope":{"skills_in_focus":["presentation.conectar_dolor","presentation.valor_personalizado","presentation.beneficio_no_caracteristica"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":10,"max_duration_seconds":210,"min_turns_before_evaluation":2},"phases":{"i_do":{"briefing":"Escucha mi presentación y nota una cosa: cada frase nace del dolor que el cliente me contó. No presento mi catálogo — presento SU problema resuelto.","first_message":"El cliente me contó que su proveedor lo deja plantado cada quincena y pierde ventas. Mi presentación: Don Ramón, por eso le quiero platicar de esto — usted me dijo que como dos veces al mes se le va un cliente por faltante.\n\nYo paso por esta zona cada semana, y lo que se le acaba un lunes lo tiene el siguiente lunes en su mostrador. O sea: esos clientes que hoy manda a la competencia...\n\ntienen dónde comprarle a usted. — ¿Notaste?\n\nSu dolor, mi solución, y el beneficio en SU caja. Cero catálogo genérico."},"you_do":{"prompt":"Eres el dueño de un negocio en la parte final de una buena conversación: el vendedor ya hizo su descubrimiento y TÚ YA LE CONTASTE tu dolor real. Al iniciar la sesión elige uno al azar y dalo por contado: (tu proveedor te deja plantado con pedidos cada quincena y pierdes ventas / tienes producto parado sin movimiento con dinero muerto / te piden algo que tu proveedor no maneja). Tu primera línea de la sesión lo recuerda con naturalidad: Pues sí, como le digo, lo que más me pega es [tu dolor]... a ver, ¿usted qué trae? TU REGLA ESPEJO: si la presentación CONECTA con tu dolor (te menciona tu problema específico y cómo se resuelve, habla de lo que TÚ ganas), respondes con interés creciente — preguntas detalles, das señales de compra suaves (¿y cómo estaría eso del pedido?, ¿cada cuánto surten?). Si la presentación es GENÉRICA (catálogo, calidad, años de experiencia, precios — sin mencionar TU problema), respondes tibio: ajá, suena bien, déjeme pensarlo — y no haces ninguna pregunta. Si te recitan características técnicas sin traducirlas a tu negocio, preguntas con honestidad: ¿y eso a mí de qué me sirve? TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.","objective":"El vendedor construye una presentación 100% conectada al dolor declarado del cliente: (1) abre nombrando el dolor específico que el cliente contó (usted me dijo que...), (2) presenta su producto/servicio como solución directa de ESE problema, y (3) traduce cada característica a beneficio concreto en el negocio del cliente (dinero, clientes, tranquilidad). El scope se cubre cuando el cliente mostró interés real — hizo al menos una pregunta de detalle o soltó una señal de compra."},"closing":{"message":"Esa presentación no la puede dar ningún otro vendedor — porque está hecha con lo que ESTE cliente te contó. Eso es presentar con sistema. Vamos al detalle.","message_incomplete":"Ahi lo dejamos, ya vi como conectas con lo que le duele. Vamos al desglose."}},"version":"1.0.1","i_do_type":"demo","failure_criteria":[{"id":"presentacion_generica","regla_id":"present.dos_mitades","severity":"critical","description":"Presenta catálogo, calidad, años o precios SIN conectar con el dolor declarado del cliente — la presentación serviría idéntica para cualquier negocio. El pecado central de este mundo.","severity_override":{"razon":"escalada: habilidad espejo del nodo","default":"major"}},{"id":"caracteristicas_sin_beneficio","regla_id":"present.caracteristica_sin_traducir","severity":"major","description":"Recita datos técnicos o de catálogo sin traducirlos a lo que el cliente gana — el cliente pregunta ¿y eso a mí de qué me sirve?"},{"id":"baja_su_valor","regla_id":"close.descuento_de_panico","severity":"major","description":"Devalúa su propia oferta ante la primera tibieza: ofrece la línea económica, se retracta, o pide disculpas por el precio antes de que se lo cuestionen."},{"id":"monologo","regla_id":"monologo","severity":"minor","description":"Presentación en bloque de un solo turno larguísimo, sin pausas ni participación del cliente."}],"success_criteria":[{"id":"presentation.conectar_dolor","weight":0.4,"regla_id":"present.dos_mitades","description":"Abre la presentación nombrando explícitamente el dolor que el cliente declaró (usando sus palabras o muy cercanas) y presenta la oferta como solución directa de ESE problema — el puente dolor→solución es visible en el texto."},{"id":"presentation.valor_personalizado","weight":0.35,"regla_id":"present.beneficio_no_caracteristica","description":"La presentación está construida para ESTE cliente: referencias a su negocio, su situación y su dolor. Cero frases de catálogo genérico que servirían igual en cualquier otro negocio."},{"id":"presentation.beneficio_no_caracteristica","weight":0.25,"regla_id":"present.beneficio_no_caracteristica","description":"Traduce características a beneficios: cada dato del producto aparece acompañado de lo que el cliente GANA (deja de perder ventas, recupera dinero parado, clientes que regresan) — no specs sueltas."}]}$g$::jsonb WHERE id = '4.1' AND practice_script->>'version' = '1.0.0';

UPDATE public.nodes SET practice_script = $g${"notes":"v2.0.0 Nodo nuevo. El espejo usa la pregunta que el vendedor promedio teme (y eso a mi de que me sirve?) como consecuencia automatica de no traducir. Ensena sin regano. v2.0.2 (mensaje 135, Emilio 5-nov): sin promesa_sin_ancla; las promesas sin sustento se enseñan en las balas (4.5 y 4.6) y ahí se califican.","scope":{"skills_in_focus":["presentation.beneficio_no_caracteristica"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":10,"max_duration_seconds":210,"min_turns_before_evaluation":3},"phases":{"i_do":{"briefing":"Fíjate en que nunca dejo una característica sola. Digo lo que el producto es, y en la misma frase digo qué gana él con eso.\n\nLa característica es mi lenguaje; el beneficio es el suyo. Si solo hablo el mío, me escucha sin entender.","first_message":"Este maneja una formulación más estable a temperatura alta. Qué significa para usted: le dura más antes del siguiente cambio, o sea menos servicios al año por unidad y menos gente reclamándole.\n\nY como le dura más, su cliente regresa contento en lugar de regresar a quejarse."},"you_do":{"prompt":"Eres el dueno de un negocio, atento y de buena disposicion, escuchando lo que el vendedor te presenta. Ya platicaron antes y ya le contaste que tu problema es que pierdes ventas cuando te falta producto. TU REGLA PRINCIPAL: reaccionas segun el vendedor traduzca o no. Si menciona una CARACTERISTICA sin traducirla a un beneficio concreto (una especificacion tecnica, un dato del producto, una certificacion, una marca), respondes con desinteres educado y le devuelves la pregunta que el vendedor promedio teme: y eso a mi de que me sirve? / ajam, y eso que me ayuda? / si, y? SI la traduce a algo concreto que tu ganas (dinero, mas clientes, menos problemas, tiempo, tranquilidad), te enganchas: asientes, preguntas mas al respecto, y conectas con tu propia situacion. Si te tira MUCHAS caracteristicas juntas sin traducir ninguna, te saturas y dices que lo tienes que pensar. NUNCA traduzcas tu por el: si el no dice el beneficio, tu no lo adivinas. Responde en 1 o 2 frases. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.","objective":"El vendedor traduce cada caracteristica que menciona a un beneficio concreto para ese cliente: dinero, clientes, tiempo o tranquilidad. El scope se cubre cuando el cliente se engancha con al menos dos beneficios traducidos y conecta con su propia situacion."},"closing":{"message":"Eso es traducir. Dijiste lo que el producto es y, en la misma frase, lo que él gana. La característica es tu idioma; el beneficio es el suyo. El que solo habla el propio, presenta para sí mismo. Vamos al detalle.","message_incomplete":"Ahí lo dejamos, ya vi cómo presentas. Vamos al desglose y te digo cuáles se quedaron sin traducir."}},"version":"2.0.2","i_do_type":"demo","failure_criteria":[{"id":"caracteristica_sin_traducir","regla_id":"present.caracteristica_sin_traducir","severity":"major","description":"Menciona especificaciones, datos tecnicos o certificaciones sin decir que gana el cliente con eso. El cliente escucha sin entender y contesta y eso a mi de que me sirve."},{"id":"catalogo","regla_id":"present.caracteristica_sin_traducir","severity":"major","description":"Encadena varias caracteristicas seguidas sin traducir ninguna. El cliente se satura y se defiende con un lo voy a pensar."},{"id":"beneficio_generico","regla_id":"present.caracteristica_sin_traducir","severity":"minor","description":"Traduce a un beneficio que serviria para cualquier negocio (es de calidad, le va a gustar) en lugar de conectarlo con la situacion concreta del cliente.","severity_override":{"razon":"incidental: fuera del foco del nodo","default":"major"}}],"success_criteria":[{"id":"presentation.beneficio_no_caracteristica","weight":1,"regla_id":"present.beneficio_no_caracteristica","description":"Cada caracteristica que menciona va acompanada de su traduccion a algo concreto que el cliente gana: mas dinero, mas clientes, menos tiempo perdido o menos problemas. La traduccion debe ser especifica de ESE negocio, no generica. Mencionar la caracteristica sola no cumple, aunque sea impresionante."}]}$g$::jsonb WHERE id = '4.2' AND practice_script->>'version' = '2.0.1';

UPDATE public.nodes SET practice_script = $g${"notes":"El Actor reacciona a imágenes, no a datos — la mecánica espejo enseña la diferencia entre explicar y pintar en vivo. La señal de scope: el cliente COMPLETÓ una escena con detalles propios (la prueba de que entró en ella).","scope":{"skills_in_focus":["presentation.pintar_imagenes","presentation.conectar_dolor"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":10,"max_duration_seconds":210,"min_turns_before_evaluation":2},"phases":{"i_do":{"briefing":"Escucha la diferencia entre EXPLICAR y PINTAR. Explicar informa.\n\nPintar hace que el cliente se VEA en la escena — y de esa escena ya no se quiere salir.","first_message":"Explicar suena así: El producto tiene buen movimiento y márgenes competitivos. — Correcto, y frío.\n\nPintar suena así: Imagínese la quincena que viene: llega el cliente de siempre por sus tres litros... y ahora sí los tiene.\n\nSe los lleva, le deja la ganancia a usted y no al de enfrente — y de pasada se lleva unas grasas porque ya que estaba aquí. ¿Ve la diferencia?\n\nEl cliente ya se vio ganando.\n\nAhora el producto no es un dato: es esa mañana."},"you_do":{"prompt":"Eres el dueño de un negocio al final de un buen descubrimiento: ya contaste tu dolor. Elige uno al azar y menciónalo en tu primera línea: (pierdes ventas por faltantes de tu producto estrella / tienes dinero muerto en producto que no se mueve / te piden algo que tu proveedor no maneja). TU REGLA ESPEJO — reaccionas a IMÁGENES, no a datos: si el vendedor te pinta una escena concreta de TU negocio con el problema resuelto (imagínese que..., piense en la próxima quincena cuando..., usted abriendo la cortina y...), entras en la escena: la completas con detalles tuyos (pues sí, y hasta podría..., no pues eso me ahorraría el coraje de...), y tu interés crece visiblemente. Si el vendedor solo explica con datos y adjetivos (buena calidad, excelente margen, muy rentable), respondes cortés pero plano: ajá, ok, suena bien — sin entrar en ninguna escena. Si la escena que pinta es genérica y no usa TU dolor ni TU negocio, respondes: pues sí, como en todos lados, supongo. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.","objective":"El vendedor presenta pintando al menos DOS imágenes concretas del negocio del cliente con el problema resuelto: escenas específicas (con momento, personaje o situación reconocible de SU operación) construidas sobre el dolor declarado — no descripciones abstractas del producto. El scope se cubre cuando el cliente ENTRÓ en al menos una escena: la completó con sus propios detalles o expresó verse en ella."},"closing":{"message":"El cliente se vio en la escena — y de ahí ya no se quiso salir. Eso es pintar imágenes: la parte del cine que tiene este trabajo. Vamos al detalle.","message_incomplete":"Ahi lo dejamos, ya vi como pintas la imagen. Vamos al desglose."}},"version":"1.0.2","i_do_type":"demo","failure_criteria":[{"id":"explica_sin_pintar","regla_id":"present.pintar_imagenes","severity":"major","description":"Presenta solo con datos y adjetivos (calidad, margen, rentable, confiable) sin construir una sola escena visualizable — el cliente permanece fuera, escuchando información.","espejo_de":"presentation.pintar_imagenes"},{"id":"imagen_generica","regla_id":"present.pintar_imagenes","severity":"major","description":"Sus escenas no usan el dolor ni el contexto del cliente — son postales genéricas de éxito que servirían para cualquiera (le va a ir muy bien, va a vender mucho).","espejo_de":"presentation.pintar_imagenes"},{"id":"presentacion_generica","regla_id":"present.dos_mitades","severity":"major","description":"Ignora el dolor declarado y presenta catálogo.","espejo_de":"presentation.conectar_dolor"},{"id":"monologo","regla_id":"monologo","severity":"minor","description":"Pinta sin pausa — no deja al cliente entrar a la escena."}],"success_criteria":[{"id":"presentation.pintar_imagenes","weight":0.6,"regla_id":"present.pintar_imagenes","description":"Pinta al menos dos escenas concretas y específicas del negocio del cliente con el problema resuelto: usa lenguaje de visualización (imagínese, piense en, va a ver que) con momento, personajes o situaciones reconocibles de SU operación. Las escenas logran que el cliente entre: las complete o se vea en ellas."},{"id":"presentation.conectar_dolor","weight":0.4,"regla_id":"present.dos_mitades","description":"Las imágenes nacen del dolor declarado: la escena pintada es exactamente ese problema resuelto — no una fantasía genérica de éxito."}]}$g$::jsonb WHERE id = '4.3' AND practice_script->>'version' = '1.0.1';

UPDATE public.nodes SET practice_script = $g${"notes":"v2.0.0 Nodo nuevo. Corrige la doctrina deformada: las balas son del VENDEDOR (hechos positivos sobre ti, producto y precio), no objeciones del cliente. El espejo tiene cuatro estados: dosificada sube, rafaga satura, vaga no mueve, exagerada baja. v2.0.2 (mensaje 135): sin pitch_prematuro (usaba una regla de presentar antes de diagnosticar para castigar llegar al precio, y el precio sí va en la presentación); en la presentación unas tres balas antes del precio es lo normal (present.balas).","scope":{"skills_in_focus":["objections.bullet_theory"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":10,"max_duration_seconds":210,"min_turns_before_evaluation":3},"phases":{"i_do":{"briefing":"Fíjate en el ritmo. Disparo una bala, dejo que aterrice, y veo cómo reacciona antes de disparar la siguiente.\n\nEn la presentación, unas tres antes del precio es lo normal. Y fíjate en algo más: me guardo las mejores.\n\nTodavía no llego a las objeciones, y ahí es donde de verdad las voy a necesitar.","first_message":"Mire, algo que le puede servir: llevamos catorce años surtiendo esta zona, así que cuando hay desabasto general nosotros seguimos entregando. ...\n\nY le comento otra cosa: nuestro tiempo de entrega es de veinticuatro horas dentro de la ciudad."},"you_do":{"prompt":"Eres el dueno de un negocio, ya en confianza con el vendedor y escuchando su propuesta con interes moderado. TU REGLA PRINCIPAL: tu nivel de interes sube y baja segun COMO disparen las balas. Si el vendedor da UN hecho positivo concreto y te deja reaccionar, tu interes SUBE de manera visible: comentas, preguntas mas, te enganchas. Si te suelta de jalon todo lo que tiene —una avalancha de hechos en el mismo turno, sin dejarte reaccionar—, te saturas: tu interes sube un momento y luego CAE, y respondes con algo como pues suena bien todo, dejeme lo pienso. Si el hecho es VAGO o generico (somos los mejores, tenemos calidad, damos buen servicio) no cuenta como bala: contestas con cortesia neutra y tu interes no se mueve. Si el vendedor dice algo que suena EXAGERADO o poco creible, tu interes BAJA y te pones esceptico: pregunta desconfiada tipo a poco?, y todo eso como me lo garantiza? NUNCA hagas objeciones de precio ni de competencia en este ejercicio. Responde en 1 o 2 frases. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.","objective":"El vendedor sube el impulso soltando balas concretas poco a poco, conforme hace falta, midiendo la reaccion entre cada una, sin saturar y sin exagerar. El scope se cubre cuando el interes del cliente subio de forma sostenida con al menos dos balas bien colocadas."},"closing":{"message":"Eso es controlar el impulso. Balas reales, una a la vez, midiendo la reacción. Y lo más importante: te quedan balas. Cuando llegues a las objeciones vas a entender por qué eso importa tanto. Vamos al detalle.","message_incomplete":"Ahí lo dejamos, ya vi cómo disparas. Vamos al desglose y te digo cómo quedó tu munición."}},"version":"2.0.2","i_do_type":"demo","failure_criteria":[{"id":"vacia_las_balas","regla_id":"present.dosificacion_balas","severity":"major","description":"Suelta todas sus balas de jalón, sin que haga falta. El cliente se satura, el impulso sube y cae, y el vendedor se queda sin munición para cuando el cliente ponga razones."},{"id":"balas_vagas","regla_id":"present.bala_generica","severity":"major","description":"Afirmaciones genericas sin dato concreto: somos los mejores, tenemos calidad, damos buen servicio. No mueven el impulso porque cualquiera las dice."},{"id":"bala_inflada","regla_id":"present.bala_generica","severity":"critical","description":"Infla una bala hasta volverla increíble (los mejores de todo el país, jamás hemos fallado una entrega). El cliente se pone escéptico y el impulso baja.","severity_override":{"razon":"escalada: habilidad espejo del nodo","default":"major"}}],"success_criteria":[{"id":"objections.bullet_theory","weight":1,"regla_id":"present.balas","description":"Dispara balas CONCRETAS sobre sí mismo, su producto o su precio: datos, años, tiempos, casos, condiciones específicas. Las suelta poco a poco, conforme hace falta subir el impulso, dejando reaccionar al cliente: en la presentación, unas tres antes del precio es lo normal. Afirmaciones vagas (somos los mejores, damos calidad) no cuentan como balas. Soltarlas todas de jalón no cumple, aunque sean buenas."}]}$g$::jsonb WHERE id = '4.6' AND practice_script->>'version' = '2.0.1';

UPDATE public.nodes SET practice_script = $g${"notes":"El Actor valida especificidad: hace cuentas ante números creíbles, reconoce referencias reales de zona, y ataca lo vago con ¿como quiénes? — la pregunta que desnuda el Jones vacío. El company_brain provee las referencias reales de cada empresa (clientes existentes de la zona) para que el ejemplo dinámico sea verificable. v1.0.2 (mensaje 135): la avaricia es la brecha entre lo que vale y lo que cuesta (impulse.avaricia); sin perdida_generica, que castigaba dos veces lo que el criterio ya cuenta a medias, y con la regla de otro factor.","scope":{"skills_in_focus":["impulse.avaricia","impulse.efecto_jones"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":10,"max_duration_seconds":210,"min_turns_before_evaluation":2},"phases":{"i_do":{"briefing":"Los últimos dos aceleradores. La avaricia bien usada no es codicia — es hacer visible lo que vale contra lo que le cuesta, en números de su negocio.\n\nY el efecto Jones es la fuerza más vieja del mundo: si a los de al lado les funciona, yo también quiero. Con nombres reales — o nada.","first_message":"Más por menos, con números: esta caja normalmente sale en mil doscientos; a usted le queda en mil cincuenta. Y como le deja ochenta pesos más por caja que la que maneja, son como mil doscientos extra al mes. Efecto Jones, con verdad: el negocio de la calle San José le entró hace dos meses — don Aurelio ya va en su tercer pedido.\n\nY el negocio grande de la avenida, igual.\n\n¿Nota que no presioné? Solo le mostré lo que vale contra lo que le cuesta, y le conté quién más ya lo está aprovechando."},"you_do":{"prompt":"Eres el dueño de un negocio al final de una buena presentación conectada a tu dolor (elígelo al azar como en drills previos) y estás en modo interesado-pasivo: suena bien, déjeme pensarlo. TU REGLA ESPEJO: (A) si el vendedor te muestra ganancia EXTRA con números concretos y creíbles de tu operación (margen por caja, ahorro al mes, beneficio adicional calculado), tu interés se activa: haces cuentas en voz alta (a ver, ¿ochenta por caja?...) y preguntas detalles. (B) si te da prueba social ESPECÍFICA (negocio con nombre o ubicación reconocible de tu zona, tiempo que lleva, resultado concreto), tu confianza sube: ah, ¿el de la San José? sí lo ubico... y tu resistencia baja visiblemente. (C) si la prueba social es VAGA (muchos clientes, varios negocios, todo mundo lo está llevando — sin un solo nombre o referencia concreta), respondes escéptico: ¿ah sí? ¿como quiénes? — si te contesta con algo concreto, lo aceptas; si no puede concretar, tu desconfianza sube. (D) si los números de ganancia son exagerados o redondos sin sustento (va a duplicar sus ventas), respondes: mmm, eso suena a mucho, ¿no?","objective":"El vendedor aplica los dos aceleradores con concreción: (1) hace visible la brecha entre lo que vale y lo que le cuesta, en números específicos y creíbles del negocio del cliente (precio regular contra su precio, margen, beneficio mensual calculado), y (2) da prueba social específica — al menos una referencia con nombre, ubicación o detalle reconocible, con su resultado concreto. El scope se cubre cuando el cliente hizo cuentas en voz alta O validó la referencia social, y pasó de pasivo a preguntar por el siguiente paso."},"closing":{"message":"Le mostraste la ganancia con números y le contaste quién ya la está cobrando — y su déjeme pensarlo se convirtió en cuánto y cuándo. Así trabajan estos dos. Vamos al detalle.","message_incomplete":"Ahi lo dejamos, ya vi como construyes la sensacion de ventaja. Vamos al desglose."}},"version":"1.0.2","i_do_type":"demo","failure_criteria":[{"id":"jones_se_cae","regla_id":"impulse.jones_vago","severity":"major","description":"Su prueba social se cae: cuando el cliente pregunta ¿como quiénes? o ¿a poco?, no da nada concreto, se echa para atrás o infla las cifras. El factor era teatro."},{"id":"promesa_grandilocuente","regla_id":"present.bala_generica","severity":"major","description":"Ganancias exageradas sin sustento: va a duplicar sus ventas, se va a llenar de clientes — el cliente responde eso suena a mucho."},{"id":"presion_directa","regla_id":"impulse.presion_directa","severity":"major","description":"Cambia los aceleradores por empuje frontal: no se lo pierda, todos le están entrando, apúrese."}],"success_criteria":[{"id":"impulse.avaricia","weight":0.5,"regla_id":"impulse.avaricia","description":"Hace visible la brecha entre lo que vale y lo que le cuesta, con números concretos y creíbles del negocio del cliente: precio regular contra su precio, margen por unidad, beneficio mensual calculado — cifras que el cliente puede verificar con sus propias cuentas, no promesas redondas (duplicar ventas)."},{"id":"impulse.efecto_jones","weight":0.5,"regla_id":"impulse.efecto_jones","description":"Da al menos una prueba social específica: negocio con nombre, ubicación o seña reconocible + tiempo + resultado concreto. Un muchos clientes ya lo llevan, sin nadie concreto, cuenta a medias."}]}$g$::jsonb WHERE id = '4.9' AND practice_script->>'version' = '1.0.1';

UPDATE public.nodes SET practice_script = $g${"notes":"El puente directo al M6: el cierre asumido es esta habilidad aplicada al momento de la decisión. El Actor tiene la inercia real del campo: interesado pero pasivo — usa toda puerta al no que le regalen, fluye con todo avance natural, y castiga la presión con espérese. La distinción asumir/presionar (critical) es el corazón ético del nodo. v1.1.0 (mensaje 135, Emilio 5-nov): asumir es dar opciones y que el cliente escoja (¿jueves o viernes?); decidir por él es presionar. Ya no se enseña a arreglar la presión: se enseña a hacerlo bien. Va después del tren del sí (4.12), que se califica aquí.","scope":{"skills_in_focus":["impulse.poder_asumir","presentation.tren_si_si"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":10,"max_duration_seconds":210,"min_turns_before_evaluation":2},"phases":{"i_do":{"briefing":"El último paso del poder de sugestión. Fíjate en mi lenguaje: nunca pregunto SI le interesa — asumo el interés que ya me demostró, sugiero el siguiente paso y le doy a escoger entre opciones donde las dos son un sí.\n\nYo propongo; él escoge.","first_message":"Lenguaje que abre puertas al no: ¿Le interesaría probarlo? ¿Quiere que le mande información?\n\n— cada pregunta invita un no gratis. Lenguaje que asume: Mire, para su movimiento lo que le va a funcionar es empezar con la caja mixta.\n\n¿Se la traigo el jueves o el viernes, que ando por acá? Así la quincena la agarra surtido.\n\n— ¿Notó? No pregunté si quiere: sugerí cuál y le di a escoger cuándo.\n\nEscoja lo que escoja, ya me dijo que sí."},"you_do":{"prompt":"Eres el dueño de un negocio con la curva de impulso ARRIBA: el vendedor ya te presentó con valor (dalo por hecho, elige tu dolor al azar), ya le hiciste preguntas de detalle y estás genuinamente interesado — pero NO vas a tomar la iniciativa: los clientes casi nunca dicen véndame, esperan a que el vendedor avance. TU REGLA ESPEJO: (A) si el vendedor AVANZA asumiendo con naturalidad (te sugiere el producto/cantidad específica para tu caso y te da a escoger entre opciones concretas: ¿jueves o viernes?, ¿la caja o media?), escoges con naturalidad y, si quieres, ajustas un detalle (mejor empezar con media caja) — participas en el plan. (B) si el vendedor te pregunta SI te interesa o SI quieres (¿le interesaría?, ¿quiere que...?, ¿cómo ve?), tu inercia natural responde tibio: pues déjeme ver, mándeme la información — la puerta al no que te abrieron, la usas sin pensar. (C) si el vendedor asume con PRESIÓN (decide por ti el día o la cantidad sin darte a escoger, da por cerrada una venta que no aceptaste, te apura, ignora un ajuste que pediste), te incomoda: espérese, yo no he dicho que sí. (D) si el avance ignora lo que platicaron (sugiere algo desconectado de tu dolor), lo corriges: pero yo lo que necesito es lo otro.","objective":"El vendedor avanza asumiendo el interés demostrado: sugiere el siguiente paso concreto (producto/cantidad específica para el caso) y le da a escoger al cliente entre opciones donde las dos son un sí (¿jueves o viernes?), sin abrir puertas al no y sin decidir por él — respetando los ajustes que pida. El scope se cubre cuando el cliente escogió una opción o ajustó un detalle del plan."},"closing":{"message":"No le preguntaste si quería: le sugeriste el camino y le diste a escoger, y él escogió. Eso es asumir: ni presión ni permiso. En el siguiente mundo, esta habilidad se convierte en el cierre. Vamos al detalle.","message_incomplete":"Ahí lo dejamos, ya vi cómo asumes. Vamos al desglose."}},"version":"1.1.0","i_do_type":"demo","failure_criteria":[{"id":"abre_puerta_al_no","regla_id":"close.mal_cierre","severity":"major","description":"Pide la decision con una pregunta que se contesta con un no o un dejeme pensarlo: de interes (le interesa?), de opinion (que le parece?) o de si o no sobre la compra (se lo mando?, le aparto 10 cajas?). Todas son igual de graves.","severity_override":{"razon":"incidental: error de otro paso","default":"critical"}},{"id":"asume_con_presion","regla_id":"close.asume_con_presion","severity":"critical","description":"Decide por el cliente en vez de darle a escoger: da por hecho algo que el cliente no aceptó (le dice déjeme ver y contesta ya se lo apunté), mete cantidades o condiciones nunca platicadas, o ignora un cambio que el cliente pidió.","severity_override":{"razon":"escalada: habilidad espejo del nodo","default":"major"}},{"id":"avance_desconectado","regla_id":"present.dos_mitades","severity":"major","description":"Su sugerencia ignora lo conversado: propone producto o plan desconectado del dolor y los detalles que el cliente dio."},{"id":"presion_directa","regla_id":"impulse.presion_directa","severity":"major","description":"Empuje frontal en lugar de sugerencia natural: ándele, anímese, firme aquí."}],"success_criteria":[{"id":"impulse.poder_asumir","weight":0.6,"regla_id":"close.asumir_venta","description":"Avanza asumiendo: sugiere el siguiente paso concreto (qué producto/cantidad) y le da a escoger entre opciones donde las dos son un sí (¿jueves o viernes?, ¿la caja o media?), sin una sola pregunta que abra la puerta al no (¿le interesaría?, ¿quiere que le mande info?, ¿cómo ve?) y sin decidir por él: el cliente escoge — asumir sin presionar."},{"id":"presentation.tren_si_si","weight":0.4,"regla_id":"impulse.tren_del_si","description":"El avance viene preparado: antes o durante la sugerencia, siembra al menos un sí genuino anclado en lo conversado que hace el paso siguiente sentirse natural (esto le resuelve lo de sus faltantes, ¿verdad? → entonces empezamos con...)."}]}$g$::jsonb WHERE id = '4.11' AND practice_script->>'version' = '1.0.1';

UPDATE public.nodes SET practice_script = $g${"notes":"El Actor tiene regla de honestidad de síes: solo asiente a preguntas ancladas en su realidad — castiga lo capcioso con incomodidad creciente. Esto entrena la versión ética y efectiva del tren: acuerdos genuinos, no manipulación. El tren prepara el siguiente nodo, asumir (4.11), y se cosecha en el cierre. v1.0.2 (mensaje 135): sin «surtido garantizado» ni «¿me explico?» en los ejemplos: un sí genuino es una pregunta cuya respuesta natural es sí.","scope":{"skills_in_focus":["presentation.tren_si_si","presentation.beneficio_no_caracteristica"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":10,"max_duration_seconds":210,"min_turns_before_evaluation":3},"phases":{"i_do":{"briefing":"Cuenta los síes en mi presentación. Cada pregunta que hago tiene un sí natural como respuesta — no forzado, no de manipulación barata: síes con los que el cliente de verdad está de acuerdo.\n\nCada uno sube el impulso un escalón.","first_message":"Usted me decía que lo que más coraje le da es mandar clientes a la competencia, ¿verdad? — Sí.\n\n— Y un cliente que se va por faltante, a veces ya no regresa, ¿no le ha pasado? — Sí, me ha pasado.\n\n— Entonces tener el producto cuando se lo piden le cuida justo eso, ¿verdad? — Pues sí.\n\n— Tres síes. El cliente lleva tres escalones de acuerdo conmigo antes de que hablemos de ningún pedido.\n\nEse es el tren."},"you_do":{"prompt":"Eres el dueño de un negocio al final de un buen descubrimiento: ya contaste tu dolor (elígelo al azar: faltantes que te cuestan ventas / producto parado sin movimiento con dinero muerto / línea que tus clientes piden y no consigues) y lo mencionas en tu primera línea. TU REGLA DE SÍES: eres honesto — respondes SÍ solo a preguntas cuyo contenido de verdad coincide con lo que contaste o con sentido común evidente de tu negocio. Si la pregunta conecta con tu dolor o tu realidad, respondes sí con naturalidad y algo de detalle (pues sí, la verdad sí...). Si la pregunta es capciosa, hueca o de manipulación obvia (¿verdad que usted quiere ganar más dinero?), respondes incómodo y evasivo: pues... como todos, supongo. Si te hacen 2+ preguntas capciosas, tu desconfianza sube y lo dices: oiga, ¿a dónde va con tanto rodeo? Si el vendedor presenta afirmando todo sin preguntarte nada, escuchas cortés pero al final respondes tibio: ajá, suena bien, déjeme pensarlo.","objective":"El vendedor presenta su solución construyendo un tren de al menos TRES síes naturales: preguntas genuinas ancladas en el dolor declarado y la realidad del cliente (usted me decía que X, ¿verdad? / eso le cuesta ventas, ¿no?/ le serviría que Y, ¿verdad?) que el cliente responde afirmativamente con comodidad. Las preguntas se intercalan con la presentación — no son un interrogatorio al final. El scope se cubre al lograr el tercer sí natural del cliente dentro de una presentación conectada."},"closing":{"message":"Tres síes: tres escalones de acuerdo antes de hablar de ningún pedido. En el siguiente nodo vas a ver para qué sirven: asumir. Vamos al detalle.","message_incomplete":"Ahí lo dejamos, ya vi cómo encadenas los acuerdos. Vamos al desglose."}},"version":"1.0.2","i_do_type":"demo","failure_criteria":[{"id":"si_capcioso","regla_id":"impulse.tren_del_si","severity":"major","description":"Preguntas de manipulación hueca o capciosa (¿verdad que quiere ganar más?, ¿verdad que la calidad es importante?) — el cliente se incomoda o evade. El tren del sí funciona con acuerdos genuinos, no con trampas retóricas.","severity_override":{"razon":"escalada: habilidad espejo del nodo","default":"minor"}},{"id":"interrogatorio","regla_id":"discovery.interrogatorio","severity":"minor","description":"Dispara las preguntas en ráfaga al final en lugar de intercalarlas — se siente examen, no conversación."},{"id":"cierra_con_afirmacion","regla_id":"impulse.tren_del_si","severity":"minor","description":"Presenta todo en afirmaciones sin sembrar un solo sí — el cliente escucha pasivo y responde tibio.","espejo_de":"presentation.tren_si_si"},{"id":"presentacion_generica","regla_id":"present.dos_mitades","severity":"major","description":"El tren corre sin conexión al dolor declarado — síes sobre generalidades."}],"success_criteria":[{"id":"presentation.tren_si_si","weight":0.6,"regla_id":"impulse.tren_del_si","description":"Construye al menos tres preguntas de sí natural intercaladas en la presentación: ancladas en el dolor declarado o la realidad evidente del cliente, formuladas con suavidad (¿verdad?, ¿no le ha pasado?), y que el cliente responde afirmativamente con comodidad — sin incomodidad ni evasivas."},{"id":"presentation.beneficio_no_caracteristica","weight":0.4,"regla_id":"present.beneficio_no_caracteristica","description":"El contenido entre pregunta y pregunta sigue siendo presentación de valor: beneficios concretos conectados al dolor — el tren corre sobre rieles de valor, no en el vacío."}]}$g$::jsonb WHERE id = '4.12' AND practice_script->>'version' = '1.0.1';

UPDATE public.nodes SET practice_script = $g${"notes":"v2.0.0 Nodo nuevo. Une price_breakdown con Close With Action porque en campo son un solo movimiento. El espejo castiga el silencio con la consecuencia real: el cliente toma el control y se evade. Segunda aparicion de CWA, ahora en version fuerte.","scope":{"skills_in_focus":["presentation.price_breakdown","flow.close_with_action"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":10,"max_duration_seconds":210,"min_turns_before_evaluation":3},"phases":{"i_do":{"briefing":"Dos cosas que mirar.\n\nPrimero: bajo el precio en escalones y cada bajada tiene su motivo dicho en voz alta.\n\nSegundo, y más importante: fíjate en que NO hago pausa después del último número. En la misma respiración ya lo estoy moviendo al siguiente paso.\n\nNo espero a que reaccione.","first_message":"Mire, la caja normalmente le sale en mil doscientos. Como es su primer pedido con nosotros, le queda en mil cincuenta.\n\nY si me lo maneja de contado, se lo dejo en novecientos sesenta: son doscientos cuarenta de ahorro.\n\nPara que lo tenga esta semana, ¿le acomoda más jueves o viernes?"},"you_do":{"prompt":"Eres el dueno de un negocio. Ya escuchaste la presentacion, te intereso, y ahora el vendedor te va a hablar de precio. TU REGLA PRINCIPAL: reaccionas a DOS cosas, el desglose y lo que pasa despues del numero. SOBRE EL DESGLOSE: si te da un solo numero sin escalones, lo recibes como un gasto y respondes con reserva (esta un poco elevado / dejeme ver). Si te lo baja en escalones PERO sin decir por que baja, desconfias y te vuelves regateador: entonces el primero estaba inflado? / a ver, y si le pago todo junto en cuanto me lo deja? Si te lo baja en escalones CON un motivo nombrado en cada uno, el ahorro se te hace visible y lo recibes bien: comentas el ahorro o preguntas por condiciones. SOBRE EL SILENCIO, esto es lo mas importante: si despues del ultimo numero el vendedor se queda callado o espera tu reaccion, TU tomas el control y dices dejeme lo pienso / lo consulto y le aviso / dejeme ver como ando de flujo, y a partir de ahi te vuelves evasivo el resto de la sesion. Si el vendedor da el numero y AVANZA de inmediato con una pregunta concreta del siguiente paso, contestas esa pregunta con naturalidad y la conversacion sigue adelante. NUNCA regreses tu a la conversacion despues de un silencio. Responde en 1 o 2 frases. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.","objective":"El vendedor presenta el precio en escalones con un motivo nombrado en cada uno, y avanza de inmediato con una pregunta del siguiente paso, sin dejar silencio despues del numero. El scope se cubre cuando el cliente contesta esa pregunta y la conversacion sigue avanzando en lugar de quedarse en lo voy a pensar."},"closing":{"message":"Eso es presentar precio. Bajaste en escalones con motivo, así que el cliente vio un ahorro en lugar de un gasto. Y no le dejaste el silencio para pensarlo: avanzaste tú. Esas dos cosas juntas son la diferencia entre un «lo voy a pensar» y una fecha de entrega. Vamos al detalle.","message_incomplete":"Ahí lo dejamos. Vamos al desglose y te digo cómo cayó ese precio."}},"version":"2.0.2","i_do_type":"demo","failure_criteria":[{"id":"silencio_despues_del_precio","regla_id":"close.devuelve_el_volante","severity":"critical","description":"Da el precio y se queda esperando la reaccion del cliente. En ese silencio el cliente dice lo voy a pensar y la venta se enfria. Es el error mas caro de toda la presentacion.","severity_override":{"razon":"escalada: habilidad espejo del nodo","default":"major"}},{"id":"precio_sin_escalones","regla_id":"present.precio_unico","severity":"major","description":"Da un solo numero. El cliente lo recibe como gasto puro, sin ahorro visible que compensarlo."},{"id":"escalon_sin_motivo","regla_id":"present.escalon_sin_motivo","severity":"major","description":"Baja el precio sin decir por que. Le comunica al cliente que el primer numero estaba inflado, y lo convierte en regateador."},{"id":"pide_aprobacion","regla_id":"close.pide_aprobacion","severity":"major","description":"Despues del precio pregunta que le parece, como lo ve, si le interesa. Le entrega el control justo en el momento mas delicado.","severity_override":{"razon":"incidental: error de otro paso","default":"critical"}}],"success_criteria":[{"id":"presentation.price_breakdown","weight":0.5,"regla_id":"present.triple_desglose","description":"Presenta el precio en escalones descendentes, con un MOTIVO nombrado en cada bajada (cliente nuevo, volumen, pago de contado, promocion vigente). Un solo numero no cumple. Bajar sin motivo tampoco: destruye la credibilidad del primer precio. El ahorro debe quedar explicito."},{"id":"flow.close_with_action","weight":0.5,"regla_id":"close_with_action","description":"Despues del ultimo numero avanza de inmediato, en la misma intervencion, con una pregunta concreta del siguiente paso cuya respuesta solo tiene sentido si el cliente sigue adelante (fecha de entrega, forma de pago, un dato para el registro). Cero silencio, cero espera de reaccion, cero preguntar si le parece bien."}]}$g$::jsonb WHERE id = '4.14' AND practice_script->>'version' = '2.0.1';

UPDATE public.nodes SET practice_script = $g${"notes":"v2.1.0 (mensaje 135, Emilio 5-nov): el hueco se presenta con la misma balanza y las mismas balas (producto, servicio, precio) escogidas para su caso; «un proveedor menos» solo cuando aplica (el cliente deja ver que le pesa tratar con tantos proveedores). El cliente decide al azar si le pesa o si prefiere tener dos. El espejo: atacar cierra, solo precio no mueve, una bala que le sirve abre, pedir que pruebe asusta, convicción con razón convence, garantizar desconfía.","scope":{"skills_in_focus":["presentation.consolidacion_proveedor","presentation.beneficio_no_caracteristica"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":10,"max_duration_seconds":210,"min_turns_before_evaluation":3},"phases":{"i_do":{"briefing":"Tres cosas que mirar, y las tres van contra el instinto.\n\nNo digo una sola palabra en contra del otro proveedor.\n\nNo le vendo el producto, que ya lo tiene: le doy una bala que le sirva a él. Aquí, una de servicio que le baja el costo.\n\nY no le pido que pruebe. Le doy mi convicción con la razón detrás, y ahí me callo.","first_message":"Ah, mire, eso lo maneja con otro. Qué bueno que lo tenga cubierto.\n\nNosotros también lo traemos, de las mismas marcas que ya le surtimos.\n\nY como ya lo visito cada semana, se lo puedo traer en la misma entrega de lo demás, sin pedido aparte.\n\nYo no le puedo garantizar nada, pero estoy seguro de que se le va a mover — se lo digo porque en los negocios de por acá es de lo que más sale."},"you_do":{"prompt":"REGLA NUMERO CERO: eres un cliente CONTENTO con su proveedor actual. No tienes quejas de el y no las vas a inventar. Si el vendedor te pregunta si te falla, contestas con sinceridad que no.\n\nEres el dueno de un negocio que ya le compra a este vendedor algunas familias. Adopta el tipo de negocio y las familias del contexto de la empresa. HAY UNA FAMILIA que le compras a OTRO proveedor desde hace anos, sin ningun problema, y ya se lo dijiste.\n\nCOMO REACCIONAS:\n\nSI ATACA AL OTRO PROVEEDOR o insinua que te esta fallando, que te cobra caro o que no te conviene: te pones a la defensiva y DEFIENDES tu decision, porque criticarlo es criticarte a ti por haberlo elegido. A partir de ahi te cierras y ya no te interesa.\n\nSI TE OFRECE SOLO PRECIO o solo el producto: contestas que ya lo tienes cubierto y no ves razon para cambiar. Tu interes no se mueve.\n\nSI TE DA UNA RAZON QUE TE SIRVE A TI —una bala de producto, servicio o precio que te sube el valor o te baja el costo: que ya te visita y te lo trae en la misma entrega sin pedido aparte, una presentacion que te acomoda, un descuento con su motivo—: te interesa de verdad y preguntas mas.\n\nTU POSTURA SOBRE PROVEEDORES (eligela al azar al empezar y sostenla toda la sesion; no la menciones si no te preguntan): (a) te pesa tratar con tantos proveedores: si el vendedor te pregunta como manejas tus pedidos o tus proveedores, lo dices (la verdad si es un relajo andar con tantos), y entonces tener uno menos SI te convence; (b) prefieres tener dos proveedores para lo mismo, por si uno te falla: si el vendedor te dice que asi tendras un proveedor menos, contestas que a ti te conviene tener dos, por si uno te falla, y ese argumento no te mueve (otra razon si puede).\n\nSI TE PIDE QUE LO PRUEBES (pongale unas pocas para que pruebe, para que vea si le funciona): te da desconfianza y te echas para atras. Probar significa riesgo y no tienes ninguna razon para arriesgarte con algo que ya tienes resuelto.\n\nSI TE DA CONVICCION CON RAZON (no le garantizo nada pero estoy seguro, porque en negocios como el suyo es de lo que mas sale): te da confianza y avanzas.\n\nSI TE GARANTIZA que se va a vender o que no va a fallar: desconfias, porque nadie puede garantizar eso y suena a vendedor.\n\nResponde en 1 o 2 frases, natural.","objective":"El vendedor presenta la familia que el cliente compra con otro proveedor sin atacarlo, con una bala de producto, servicio o precio que le sirva a SU caso (por ejemplo: como ya lo visita, se lo trae en la misma entrega), y cierra el argumento con convicción respaldada por una razón — sin garantizar y sin pedir que pruebe. «Un proveedor menos» solo cuenta si el cliente dejó ver que le pesa tratar con tantos. El scope se cubre cuando el cliente muestra interés real y pregunta más."},"closing":{"message":"Eso es presentar un hueco. No atacaste a nadie, le diste una bala que le sirve a él, y cerraste con convicción en lugar de pedirle permiso para experimentar. Vamos al detalle.","message_incomplete":"Ahí lo dejamos. Vamos al desglose y te digo cómo cayó esa propuesta."}},"version":"2.1.0","i_do_type":"demo","failure_criteria":[{"id":"ataca_al_proveedor","regla_id":"present.ataca_proveedor","severity":"critical","description":"Critica, minimiza o insinua algo negativo del proveedor actual. Si el cliente lleva anos con el, criticarlo es criticar su decision, y la gente defiende sus decisiones. Cierra la puerta de inmediato."},{"id":"pide_que_pruebe","regla_id":"present.pide_que_pruebe","severity":"major","description":"Le pide al cliente que pruebe el producto para ver si le funciona. Le pasa el riesgo a el, y la gente no quiere experimentar con algo que ya tiene resuelto."},{"id":"garantiza","regla_id":"present.garantiza","severity":"critical","description":"Garantiza que el producto se va a vender o que no va a fallar. Es una promesa que no controla, y suena a vendedor. La conviccion sirve; la garantia destruye.","severity_override":{"razon":"escalada: habilidad espejo del nodo","default":"major"}},{"id":"solo_precio","regla_id":"present.caracteristica_sin_traducir","severity":"major","description":"Compite unicamente por precio o por caracteristicas del producto. Contra un proveedor establecido eso no alcanza: el cliente ya tiene eso cubierto."},{"id":"anuncia_plan_b","regla_id":"present.plan_b","severity":"minor","description":"Ofrece ajustarlo si no se mueve. Le mete una duda que no tenia y desmiente la conviccion que acaba de afirmar.","severity_override":{"razon":"incidental: fuera del foco del nodo","default":"major"}},{"id":"proveedor_menos_sin_que_aplique","regla_id":"present.consolidacion_falsa","severity":"major","description":"Le dice al cliente que con él tendrá un proveedor menos sin que el cliente haya dejado ver que le pesa tratar con tantos proveedores. Esa bala no le aplica a su caso: muchos negocios tienen dos proveedores para lo mismo, a propósito.","espejo_de":"presentation.consolidacion_proveedor"}],"success_criteria":[{"id":"presentation.consolidacion_proveedor","weight":0.6,"regla_id":"present.argumento_del_hueco","description":"Le da al cliente una razón que corresponde a SU caso: una bala de producto, servicio o precio que le sube el valor o le baja el costo (por ejemplo: como ya lo visita, se lo trae en la misma entrega), en lugar de competir solo por precio o por producto. «Un proveedor menos» solo vale si el cliente dejó ver que le pesa tratar con tantos proveedores. Y cierra con CONVICCIÓN RESPALDADA: dice que está seguro de que se va a mover, como lo que él cree, y da la razón, sin prometerlo como un hecho. No pide que lo pruebe."},{"id":"presentation.beneficio_no_caracteristica","weight":0.4,"regla_id":"present.beneficio_no_caracteristica","description":"Traduce su bala a algo concreto que el cliente gana: menos tiempo, menos pedidos aparte, algo que se le vende más. Mencionar que también manejan esa línea, sin traducirlo a lo que gana, no cumple."}]}$g$::jsonb WHERE id = '4.15' AND practice_script->>'version' = '2.0.1';

UPDATE public.nodes SET practice_script = $g${"notes":"BOSS del Mundo 4 — el ciclo diagnóstico→presentación completo ante el arquetipo desconfiado d4. Integra M3 (capas, escucha) y M4 entero. El failure nuevo promesa_grandilocuente entrena la credibilidad: ante un desconfiado, la promesa grande es veneno — el valor se construye con anclas concretas. 18 turnos: la sesión más larga del mapa hasta ahora. v1.1.0 (oct-2026, Emilio): el boss de La Presentación califica también los factores de impulso, el triple desglose y beneficio-no-característica; valor personalizado entra en conectar con el dolor y el dolor real se queda en El Descubrimiento. v1.2.1 (mensaje 135): el precio va en la presentación (present.dos_mitades), no solo cuando el cliente lo pregunta; P de FUJPIG = poder de sugestión.","scope":{"skills_in_focus":["presentation.conectar_dolor","presentation.beneficio_no_caracteristica","presentation.pintar_imagenes","presentation.tren_si_si","impulse.factores_impulso","presentation.price_breakdown","relationship.cpr"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":18,"max_duration_seconds":420,"min_turns_before_evaluation":8},"phases":{"you_do":{"prompt":"Eres el dueño de un negocio de perfil DESCONFIADO: varios vendedores te han prometido de más y cumplido de menos, así que recibes con escepticismo cordial — escuchas, pero no crees fácil. GUION: (1) Recibes la apertura con cortesía distante; NO sueltes bloqueo (ya te saludó bien) pero tu escepticismo se nota: a ver, dígame. (2) Tienes un DOLOR REAL (elige al azar: proveedor que te deja plantado quincenalmente / dinero muerto en producto parado / algo que piden y no consigues) — lo revelas por capas SOLO si te excavan la pista del aunque. (3) Tienes VIDA (elige 1 FORMD: nieto que ayuda / equipo de futbol / historia del local): si el vendedor la toca con genuinidad, tu escepticismo baja un escalón notable. (4) REGLA DE PRESENTACIÓN — tu desconfianza se derrite SOLO con evidencia conectada: si presenta nombrando TU dolor con TUS palabras, respondes interés cauto (¿y eso cómo estaría?); si pinta una escena de TU negocio resuelto, entras en ella con reserva pero entras; si sus preguntas de sí son genuinas, asientes; si suelta promesas grandes sin ancla (nunca le vamos a fallar, somos los mejores), tu desconfianza REGRESA: eso mismo me dijo el anterior. (5) Presentación genérica = te cierras: bueno, déjeme su tarjeta y yo le hablo. (6) PRECIO: cuando la presentación ya te interesó, si el vendedor todavía no te ha dicho el precio, lo preguntas: ¿y a cómo me lo dejaría? Si te lo presenta con lo que normalmente cuesta, el descuento y por qué, y lo que te ahorras, lo tomas en serio; si suelta un número seco, te parece caro. (7) IMPULSO: si te muestra lo que pierdes por esperar, negocios como el tuyo que ya lo manejan (con nombre), o la ventaja en números de tu negocio, te mueve; si suena vago o a teatro (todos lo están comprando, solo por hoy), tu desconfianza regresa: eso mismo me dijo el anterior. Tu techo: interesado-cauto que pide detalles concretos del siguiente paso — nunca eufórico. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.","objective":"El vendedor completa el ciclo con un cliente desconfiado: excava el dolor real por capas hasta la revelación y confirmación, construye conexión personal genuina en el camino (al menos un tema FORMD), y presenta CONECTADO: abre desde el dolor con las palabras del cliente, pinta al menos una escena de su negocio resuelto, siembra al menos dos síes genuinos, traduce a beneficios concretos sin promesas grandilocuentes, sube el impulso con al menos dos factores concretos, y presenta el precio con el triple desglose. El scope se cubre cuando el desconfiado muestra interés real: pregunta por detalles concretos del siguiente paso (cómo surtirían, cada cuánto, qué necesita hacer)."},"closing":{"message":"Un desconfiado pidiéndote los detalles del siguiente paso — eso no se compra con promesas: se construye con valor. Acabas de recorrer el camino completo del diagnóstico a la presentación. El cierre te espera en el siguiente mundo. Vamos al desglose.","message_incomplete":"Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}},"version":"1.2.1","i_do_type":"demo","failure_criteria":[{"id":"presentacion_generica","regla_id":"present.dos_mitades","severity":"critical","description":"Presenta catálogo/calidad/años sin conectar con el dolor excavado — el desconfiado se cierra con un déjeme su tarjeta.","severity_override":{"razon":"boss: escalada","default":"major"}},{"id":"promesa_grandilocuente","regla_id":"present.bala_generica","severity":"major","description":"Promesas grandes sin ancla concreta (nunca fallamos, somos los mejores, se lo garantizo todo) — la desconfianza regresa: eso me dijo el anterior."},{"id":"pitch_prematuro","regla_id":"discovery.receta_sin_diagnostico","severity":"major","description":"Presenta antes de haber excavado y confirmado el dolor — recetó sin diagnóstico."},{"id":"ignora_pistas","regla_id":"discovery.escalera_capas","severity":"major","description":"Deja pasar la pista del dolor o los datos personales del cliente."},{"id":"si_capcioso","regla_id":"impulse.tren_del_si","severity":"minor","description":"Preguntas de sí capciosas o huecas que incomodan."},{"id":"explica_sin_pintar","regla_id":"present.pintar_imagenes","severity":"major","description":"Presentación de puros datos sin una sola escena.","severity_fix":"minor->major (BOSS no baja errores de su paso)","espejo_de":"presentation.pintar_imagenes"},{"id":"monologo","regla_id":"monologo","severity":"minor","description":"Bloques largos que atropellan al desconfiado."},{"id":"presion_teatral","regla_id":"impulse.presion_directa","severity":"major","description":"Mete urgencia o escasez como teatro, sin razón concreta (solo por hoy, ya casi no hay, todos lo están comprando), o presiona de frente — el desconfiado lo huele: eso mismo me dijo el anterior."}],"success_criteria":[{"id":"presentation.conectar_dolor","weight":0.15,"regla_id":"present.dos_mitades","description":"La presentación abre nombrando el dolor confirmado con las palabras del cliente, y toda la oferta se articula como solución de ESE problema, personalizada a su negocio: cero frases de catálogo."},{"id":"presentation.beneficio_no_caracteristica","weight":0.1,"regla_id":"present.beneficio_no_caracteristica","description":"Traduce cada característica a lo que el cliente gana en su negocio: resultados, no especificaciones."},{"id":"presentation.pintar_imagenes","weight":0.1,"regla_id":"present.pintar_imagenes","description":"Al menos una escena concreta del negocio del cliente con el problema resuelto, que el cliente recibe entrando en ella."},{"id":"presentation.tren_si_si","weight":0.1,"regla_id":"impulse.tren_del_si","description":"Al menos dos preguntas de sí genuino ancladas en lo declarado, respondidas afirmativamente con comodidad."},{"id":"impulse.factores_impulso","weight":0.25,"regla_id":"impulse.factores","description":"Sube el impulso con al menos DOS factores de FUJPIG distintos (miedo a la pérdida, urgencia, efecto Jones, poder de sugestión, indiferencia, avaricia), concretos y anclados en el negocio del cliente. Con uno solo es parcial; un factor dicho en general cuenta a medias."},{"id":"presentation.price_breakdown","weight":0.15,"regla_id":"present.triple_desglose","description":"El precio va en la presentación: lo presenta con el triple desglose —lo que normalmente cuesta, lo que queda con cada descuento y por qué, y el ahorro visible—, aunque el cliente no lo haya preguntado. En la práctica los descuentos y sus motivos se pueden imaginar."},{"id":"relationship.cpr","weight":0.15,"regla_id":"relationship.cpr","description":"Toca al menos un tema personal FORMD con genuinidad en el momento natural — y el escepticismo del cliente baja un escalón visible."}]}$g$::jsonb WHERE id = '4.16' AND practice_script->>'version' = '1.2.0';

UPDATE public.nodes SET practice_script = $g${"notes":"v2.0.0 EXAMEN de desarrollo de cuenta (CAMPO, Emilio). Sin ayudas. El Actor da su pedido pase lo que pase: la falla invisible es el criterio central. Se puede terminar con el pedido en la mano y reprobar. v2.0.4 (mensaje 122, 2-nov-2026): el argumento del hueco depende del caso; la consolidacion no es universal (Cerebro 4.3). v2.0.5 (mensaje 135, Emilio 5-nov): el hueco se presenta con balas de producto, servicio o precio escogidas para su caso; «un proveedor menos» solo cuando el cliente deja ver que le pesa tratar con tantos proveedores. El cliente decide al azar si le pesa o si prefiere tener dos.","scope":{"skills_in_focus":["discovery.lee_el_lugar","discovery.hueco","presentation.consolidacion_proveedor","closing.cerrar_incremento","consolidation.rehash"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":18,"max_duration_seconds":360,"min_turns_before_evaluation":5},"phases":{"i_do":{"briefing":"El examen del cliente que ya te compra. Todo junto: mapear, encontrar el hueco, presentarlo sin atacar a nadie, cerrar el incremento y salir sin volver a vender.\n\nEl cliente te va a dar su pedido y quedarse contento hagas lo que hagas. Nadie te va a avisar si lo hiciste mal.","first_message":"Buenas don [nombre]! Ya lo veo con trabajo desde temprano. Como le fue con la quincena pasada?"},"you_do":{"prompt":"REGLA NUMERO CERO: eres un cliente CONTENTO y sin ningun problema. Si te preguntan si algo anda mal, contestas con sinceridad que no. NUNCA inventes dolores ni quejas.\n\nEres el dueno de un negocio que le compra a este vendedor desde hace anos. Buena relacion, lo recibes con gusto. Adopta el tipo de negocio y las familias de producto del contexto de la empresa.\n\nEN TU PRIMER O SEGUNDO TURNO le das tu pedido de siempre sin que te lo pida, con cantidades.\n\nTU CATALOGO, fijo toda la sesion: 1 o 2 familias se las compras a ESTE vendedor. Otras 2 se las compras a OTRO proveedor desde hace anos y estas conforme. Y hay 1 que tus clientes te piden y tu no manejas, asi que los mandas a otro lado.\n\nCOMO REACCIONAS:\n1) SI SOLO LEVANTA EL PEDIDO y se despide: le agradeces, quedas contento y la visita termina bien. NO le insinuas que hay mas.\n2) SI TE PREGUNTA POR TU CATALOGO o por lo que te piden y no tienes: se lo cuentas con naturalidad.\n3) SI ATACA A TU OTRO PROVEEDOR: defiendes tu decision y te cierras.\n4) SI TE DA UNA RAZON QUE CORRESPONDE A TU CASO —una bala de producto, servicio o precio que te sube el valor o te baja el costo: que ya te visita y te lo trae en la misma entrega, que se vende junto con lo que ya le compras, un descuento con su motivo—: te interesa de verdad y preguntas mas. TU POSTURA SOBRE PROVEEDORES (eligela al azar al empezar y sostenla toda la sesion; no la menciones si no te preguntan): (a) te pesa tratar con tantos proveedores: si te pregunta como manejas tus pedidos, lo dices, y entonces tener uno menos SI te convence para las familias que le compras a otro; (b) prefieres tener dos proveedores para lo mismo, por si uno te falla: si te dice que asi tendras un proveedor menos, contestas que a ti te conviene tener dos, y ese argumento no te mueve. Para la familia que no manejas, menos proveedores nunca te convence: no te reduce nada.\n5) SI TE PIDE QUE PRUEBES algo: te da desconfianza y te echas para atras.\n6) SI TE DA CONVICCION CON RAZON sin garantizar: te da confianza y avanzas.\n7) SI CIERRA PREGUNTANDO si quieres: dices que lo piensas. SI ASUME Y TE DA ALTERNATIVA: contestas y queda cerrado.\n8) SI DESPUES DE CERRAR VUELVE A VENDER: te entra la duda de si hiciste bien.\n\nTU PEDIDO BASE NUNCA SE CANCELA.\n\nResponde en 1 o 2 frases, natural.","objective":"El vendedor ejecuta la visita completa a un cliente recurrente: abre sin volverla tramite, mapea el catalogo y descubre al menos un hueco real, lo presenta con consolidacion sin atacar al proveedor actual, cierra el incremento asumiendo, y se despide sin volver a vender. El scope se cubre cuando el incremento queda confirmado."},"closing":{"message":"Hasta aqui el examen. Ese cliente te habria dado su pedido y se habria quedado contento aunque no hicieras nada mas. Vamos al desglose y vemos que tanto creciste la cuenta.","message_incomplete":"Hasta aqui el examen. Vamos al desglose."}},"version":"2.0.5","i_do_type":"demo","failure_criteria":[{"id":"solo_levanta_pedido","regla_id":"develop.visita_tramite","severity":"critical","description":"Sale unicamente con el pedido de siempre, sin explorar nada. La visita parece exitosa y no lo fue: la cuenta no crecio.","severity_override":{"razon":"boss: escalada","default":"major"}},{"id":"ataca_al_proveedor","regla_id":"present.ataca_proveedor","severity":"critical","description":"Critica o minimiza al proveedor actual del cliente."},{"id":"hueco_inventado","regla_id":"discovery.hueco_inventado","severity":"critical","description":"Afirma que al cliente le falta algo o que lo necesita sin ninguna base, o contradice lo que el cliente dijo. Preguntar, apoyarse en negocios como el suyo o decir lo que ve no es inventar."},{"id":"garantiza","regla_id":"present.garantiza","severity":"critical","description":"Garantiza que el producto se vendera o que no fallara.","severity_override":{"razon":"boss: escalada","default":"major"}},{"id":"pregunta_si_quiere","regla_id":"close.mal_cierre","severity":"major","description":"Pide la decision con una pregunta que se contesta con un no o un dejeme pensarlo: de interes (le interesa?), de opinion (que le parece?) o de si o no sobre la compra (se lo mando?, le aparto 10 cajas?). Todas son igual de graves.","severity_override":{"razon":"incidental: error de otro paso","default":"critical"}},{"id":"vuelve_a_vender","regla_id":"consolidation.sigue_vendiendo","severity":"major","description":"Despues del si sigue justificando la compra.","severity_override":{"razon":"incidental: error de otro paso","default":"critical"}},{"id":"pide_que_pruebe","regla_id":"present.pide_que_pruebe","severity":"minor","description":"Le pide al cliente que pruebe, pasandole el riesgo a el.","severity_override":{"razon":"incidental: error de otro paso","default":"major"}},{"id":"proveedor_menos_sin_que_aplique","regla_id":"present.consolidacion_falsa","severity":"major","description":"Le dice al cliente que con él tendrá un proveedor menos sin que el cliente haya dejado ver que le pesa tratar con tantos proveedores, o para una familia que no maneja. Esa bala no le aplica a su caso.","espejo_de":"presentation.consolidacion_proveedor"}],"success_criteria":[{"id":"discovery.lee_el_lugar","weight":0.2,"regla_id":"discovery.lee_el_lugar","description":"Mapea el catalogo del cliente mas alla de lo que ya le vende: que otras familias maneja y de quien las trae."},{"id":"discovery.hueco","weight":0.25,"regla_id":"discovery.hueco","description":"Descubre al menos un hueco concreto: una familia con nombre que el cliente compra en otro lado o que le piden y no maneja. Salir solo con el pedido de siempre no cumple."},{"id":"presentation.consolidacion_proveedor","weight":0.2,"regla_id":"present.argumento_del_hueco","description":"Presenta el hueco con un argumento que corresponde a SU caso: una bala de producto, servicio o precio que le sube el valor o le baja el costo (por ejemplo: como ya lo visita, se lo trae en la misma entrega, sin pedido aparte). «Un proveedor menos» solo si el cliente dejó ver que le pesa tratar con tantos proveedores; nunca para una familia que no maneja. Sin atacar al proveedor actual, con convicción respaldada por una razón, sin garantizar y sin pedir que pruebe."},{"id":"closing.cerrar_incremento","weight":0.2,"regla_id":"close.cierra_solo_incremento","description":"Cierra el incremento asumiendo, con alternativa, sin reabrir el pedido base y sin preguntar si lo quiere."},{"id":"consolidation.rehash","weight":0.15,"regla_id":"consolidation.rehash","description":"Despues del si, cierra la visita sin volver a vender y deja puesta la siguiente visita (o un referido amarrado a algo que el cliente dijo)."}]}$g$::jsonb WHERE id = '7.3' AND practice_script->>'version' = '2.0.4';

